function plainText(s){return norm(s).replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim()}
const EXACT_ONTOLOGY_TERMS=new Set(['tnf','jak','tyk','stat','c5a','p19','p40','ilc3','acpa','rankl','wnt','smad','pdgf','mtor','tlr','cgas','sting','mda5','cd20','cd40l','cd80','cd86']);
function regexEscape(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function termPosition(text,term){const t=plainText(text),q=plainText(term),exact=/\d/.test(q)||EXACT_ONTOLOGY_TERMS.has(q)||/^(?:il|ifn|cd) /.test(q);if(!exact)return t.indexOf(q);const body=regexEscape(q).replace(/\s+/g,'\\s+'),suffix=/^(?:il|ifn) \d+$/.test(q)?'(?!\\d)':'(?![a-z0-9])',re=new RegExp(`(?:^|\\s)${body}${suffix}`),m=re.exec(t);return m?m.index:-1}
function textHas(t,term){return termPosition(t,term)>=0}
function pathwayKeysFromText(text){const t=plainText(text),keys=[];PATHWAY_ONTOLOGY.filter(x=>!['broad','other'].includes(x.key)).forEach(o=>{if(o.terms.some(term=>textHas(t,term)))keys.push(o.key)});if(!keys.length)keys.push('other');return [...new Set(keys)].slice(0,4)}
function pathwayKeys(p){return pathwayKeysFromText(`${p.axis} ${p.family} ${p.role}`)}
function primaryPathwayKey(p){const text=`${p.axis} ${p.family}`;let best=null;PATHWAY_ONTOLOGY.filter(x=>!['broad','other'].includes(x.key)).forEach((o,oi)=>o.terms.forEach(term=>{const pos=termPosition(text,term);if(pos>=0&&(!best||pos<best.pos||(pos===best.pos&&oi<best.oi)))best={key:o.key,pos,oi}}));return best?.key||pathwayKeys(p)[0]||'other'}
function keysFromMedicationText(text){const t=plainText(text),keys=[];const add=k=>{if(!keys.includes(k))keys.push(k)};if(/\btnf\b/.test(t))add('tnf');if(/\bil 17(?!\d)|\bil17(?!\d)/.test(t))add('il17');if(/\bil 23(?!\d)|\bil23(?!\d)|\bp19\b|\bp40\b/.test(t))add('il23');if(/\bjak\b|\btyk2?\b|\bstat(?:1|2|3|4|5|6)?\b/.test(t))add('jakstat');if(/\bbaff\b|\bblys\b|\bcd20\b|b cell|plasma cell/.test(t))add('bcell');if(/ifnar|type i interferon|interferon alpha/.test(t))add('type1_ifn');if(/\bil 6(?!\d)|\bil6(?!\d)/.test(t))add('il6');if(/\bc5a\b|complement c5|terminal c5|\bcomplement\b/.test(t))add('complement');if(/\bil 5(?!\d)|\bil5(?!\d)|eosinoph/.test(t))add('eosinophil');if(/\bil 1(?!\d)|\bil1(?!\d)/.test(t))add('il1');if(/endothel|\bpde5\b|prostacyclin|angiotensin|ace inhibitor/.test(t))add('vascular');if(/vitamin k|antithrombin|platelet cyclooxygenase|anticoag|thrombin/.test(t))add('coagulation');if(/osteoclast|bisphosphonate|\brankl\b/.test(t))add('bone');if(/myeloperoxidase|tubulin|neutrophil/.test(t))add('neutrophil');if(/calcineurin|\bcd80\b|\bcd86\b|co stimulation/.test(t))add('tcell');if(/endolysosomal|nucleic acid sensing|\btlr\b|\bcgas\b|\bsting\b/.test(t))add('innate_sensing');if(/vegfr|fgfr|pdgfr|dermal uva|collagen|tgf|fibroblast/.test(t))add('fibrosis');if(/muscarinic/.test(t))add('secretory');if(/bacterial ribosome|androgen receptor|insulin signaling|microbiome/.test(t))add('trigger');if(/inflammasome|nlrp3|pyrin|caspase 1/.test(t))add('inflammasome');return keys}
function medDirectTargetKeys(m){const keys=keysFromMedicationText(`${m.primary} ${m.direct}`);if(keys.length)return keys;if(/glucocorticoid|folate|aicar|inosine|alkyl|mercaptopurine|phosphodiesterase|cereblon|multiple fc|immunoglobulin/.test(plainText(`${m.primary} ${m.direct}`)))return ['broad'];return ['broad']}
function medSecondaryKeys(m){const direct=new Set(medDirectTargetKeys(m)),keys=keysFromMedicationText(`${m.secondary} ${m.mechanism}`);return keys.filter(k=>!direct.has(k)).slice(0,4)}
function drugActionType(m){const t=plainText(`${m.direct} ${m.mechanism}`);return /agon|raises|increases|replacement|replaces|supplement|donor|restores|stimulates/.test(t)?'activates':'targets'}
function manifestDomains(text){const t=plainText(text),out=[];MANIFEST_ONTOLOGY.forEach(d=>{if(d.key==='other')return;const rs=(d.patterns||[]).map(p=>{try{return new RegExp(p)}catch(e){return null}}).filter(Boolean);if(rs.some(r=>r.test(t)))out.push(d.key)});return out.length?out:['other']}
function bestGrade(grades){return [...grades].sort((a,b)=>GRADE_RANK[b]-GRADE_RANK[a])[0]||'D'}
function worstGrade(grades){return [...grades].sort((a,b)=>GRADE_RANK[a]-GRADE_RANK[b])[0]||'D'}
function hashNum(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return Math.abs(h>>>0)}
function uniq(a){return [...new Set(a)]}
const TOKEN_STOP=new Set('and the with from into over under disease syndrome systemic active activity manifestations manifestation involvement symptoms condition response treatment therapy moderate severe chronic acute major selected'.split(' '));
function meaningfulTokens(text){return new Set(plainText(text).split(' ').filter(x=>x.length>3&&!TOKEN_STOP.has(x)))}
function scoreTokenOverlap(a,b){const A=meaningfulTokens(a),B=meaningfulTokens(b);let n=0;A.forEach(x=>{if(B.has(x))n++});return n}
function explicitDomainPhrase(domain,text){const t=plainText(text),rules={cutaneous:/\bskin\b|cutaneous|mucocutaneous|dermatologic/,neutrophilic:/neutrophilic|suppurative|pustular/,mucosal_ulcer:/mucosal|aphthous|oral ulcer/,ulceration:/\bulcer|tissue loss/,fibrosis:/fibro|sclero|scarring|contracture/,appendage:/hair and nail|appendage/,pain_pruritus:/pain and pruritus|pruritic/,joint:/arthritis|articular|joint disease|synovitis|osteoarticular/,enthesis_bone:/enthes|axial disease|bone disease|osteitis|skeletal/,muscle:/muscle disease|myositis|myofiber/,vascular:/vascular disease|vasculitis|vasculopathy|thrombo|ischemi|endothelial/,ocular:/ocular|eye disease|uveitis/,pulmonary:/pulmonary|lung disease|interstitial lung/,airway_cartilage:/airway|cartilage|chondritis/,renal:/renal|kidney|nephritis/,neurologic:/neurolog|cns/,hematologic:/hematolog|cytopen|clonal/,systemic:/all manifestations|all major|systemic activity|constitutional|acute phase/,glandular:/glandular|sicca|dryness/,gastrointestinal:/gastrointestinal|gi disease/,obstetric:/obstetric/,developmental:/growth|developmental/};return rules[domain]?.test(t)||false}
function effectManifestationsForCondition(e,c){const et=meaningfulTokens(e.manifestations),ed=new Set(manifestDomains(e.manifestations)),all=/\ball\b.*\b(manifestations|major|domains)\b/.test(plainText(e.manifestations));if(all)return [...c.manifestations];let matches=c.manifestations.filter(m=>{const mt=meaningfulTokens(m);for(const x of mt)if(et.has(x))return true;const common=manifestDomains(m).filter(x=>ed.has(x)&&explicitDomainPhrase(x,e.manifestations));return common.length>0});return matches}
function targetPathwaysForMed(m,paths){const direct=medDirectTargetKeys(m);if(direct.includes('broad'))return [];return paths.map(p=>({p,score:(direct.includes(primaryPathwayKey(p))?14:0)+scoreTokenOverlap(`${m.primary} ${m.direct}`,`${p.axis} ${p.family}`)+p.importance*.15})).filter(x=>x.score>=10).sort((a,b)=>b.score-a.score).slice(0,2).map(x=>x.p)}
function secondaryPathwaysForMed(m,paths){const secondary=medSecondaryKeys(m);return paths.map(p=>({p,score:(secondary.includes(primaryPathwayKey(p))?8:0)+scoreTokenOverlap(m.secondary,`${p.axis} ${p.family} ${p.role}`)})).filter(x=>x.score>=8).sort((a,b)=>b.score-a.score).slice(0,2).map(x=>x.p)}

