function drawLabel(n,rr,boxes){let label=n.label,fs=n.type==='condition'?11:10;if(label.length>36)label=label.slice(0,34)+'…';nctx.font=`${n.type==='condition'?'700':'600'} ${fs}px IBM Plex Sans`;const tw=nctx.measureText(label).width,bw=tw+10,bh=fs+8;let x=n.sx-bw/2,y=n.sy-rr-bh-5;if(n.type==='drug')y=n.sy+rr+5;if(n.type==='manifestation'){x=n.sx+rr+6;y=n.sy-bh/2}const overlap=boxes.some(q=>x<q.x+q.w&&x+bw>q.x&&y<q.y+q.h&&y+bh>q.y);if(overlap&&networkSelected?.id!==n.id&&networkHovered?.id!==n.id)return;nctx.fillStyle=document.documentElement.dataset.theme==='light'?'rgba(255,255,255,.91)':'rgba(12,17,13,.94)';roundRect(nctx,x,y,bw,bh,3);nctx.fill();nctx.strokeStyle=hexAlpha(n.color,.48);nctx.lineWidth=1;nctx.stroke();nctx.fillStyle=cssVar('--text');nctx.textAlign='center';nctx.textBaseline='middle';nctx.fillText(label,x+bw/2,y+bh/2);boxes.push({x,y,w:bw,h:bh})}
function isEdgeHighlighted(e){const focus=networkSelected?.id||networkHovered?.id;if(!focus)return false;return e.source===focus||e.target===focus}
function edgeShouldDraw(e,nodeMap){if(!nodeMap[e.source]?.visible||!nodeMap[e.target]?.visible)return false;return e.visible||isEdgeHighlighted(e)}
function draw3D(){if(!nCanvas.offsetParent)return;drawBackground();const transformedNodes=networkNodes.map(transformed),nodeMap=Object.fromEntries(transformedNodes.map(n=>[n.id,n])),focus=networkSelected?.id||networkHovered?.id,connected=new Set();if(focus)networkEdges.forEach(e=>{if(e.source===focus||e.target===focus){connected.add(e.source);connected.add(e.target)}});const drawable=networkEdges.filter(e=>edgeShouldDraw(e,nodeMap)).sort((a,b)=>((nodeMap[a.source]?.z2+nodeMap[a.target]?.z2)||0)-((nodeMap[b.source]?.z2+nodeMap[b.target]?.z2)||0));drawable.forEach(e=>{const A=nodeMap[e.source],B=nodeMap[e.target],hi=isEdgeHighlighted(e)||networkHoveredEdge?.id===e.id;if(focus&&!hi){nctx.globalAlpha=.12;drawEdge(e,A,B,false);nctx.globalAlpha=1}else drawEdge(e,A,B,hi)});const boxes=[];transformedNodes.sort((a,b)=>a.z2-b.z2).forEach(n=>{if(!n.visible)return;const dim=focus&&!connected.has(n.id)&&n.id!==focus;nctx.globalAlpha=dim?.13:1;const rr=Math.max(3,n.size*n.scale);drawNodeShape(n,rr,networkSelected?.id===n.id);if(shouldLabel(n)&&!dim)drawLabel(n,rr,boxes);nctx.globalAlpha=1})}
function visibleRelationsForNode(id){return networkEdges.filter(e=>e.source===id||e.target===id).sort((a,b)=>(b.visible?1:0)-(a.visible?1:0)||b.strength-a.strength||GRADE_RANK[b.grade]-GRADE_RANK[a.grade])}
function nodePositionText(node){return node.data.positionLogic||({condition:'Disease-context rail',pathway:'Central mechanism plane',drug:'Lower intervention plane',manifestation:'Upper phenotype plane'}[node.type]||'Semantic layout')}
function renderNetworkInspector(node=null,edge=null){
 if(edge){const A=networkNodes.find(n=>n.id===edge.source),B=networkNodes.find(n=>n.id===edge.target);$('#nodeInfo').innerHTML=`<h4>${esc(edge.label)}</h4><span class="network-badge" style="border-color:${EDGE_STYLE[edge.type]?.color};color:${EDGE_STYLE[edge.type]?.color}">${esc(EDGE_STYLE[edge.type]?.label||edge.type)}</span><div class="network-mini-grid"><div><small>Strength</small><b>${edge.strength}/5</b></div><div><small>Evidence</small><b>${gradeBadge(edge.grade)}</b></div><div><small>Source</small><b>${esc(A?.label||'')}</b></div><div><small>Target</small><b>${esc(B?.label||'')}</b></div></div><p class="node-summary">${esc(edge.detail||'No additional annotation.')}</p>${edge.refs?.length?`<div class="network-ref-list"><small>Sources</small>${refChips(edge.refs)}</div>`:''}`;$('#networkRelations').innerHTML='';return}
 if(!node){$('#nodeInfo').innerHTML='<h4>Network ready</h4><p class="node-summary">Select a node or edge. The coordinate system and routing are deterministic; proximity and direction now have defined biological meanings.</p><div class="network-coordinate-grid"><div><b>X axis</b><small>Causal stage</small></div><div><b>Y axis</b><small>Program / organ domain</small></div><div><b>Z axis</b><small>Intervention → mechanism → phenotype</small></div></div>';$('#networkRelations').innerHTML='';return}
 const typeLabel={condition:'Condition',pathway:'Immune pathway / cytokine program',drug:'Medication',manifestation:'Manifestation / organ domain'}[node.type]||node.type,refs=node.type==='pathway'?(node.data.pathway?.refs||[...(node.data.aggregate?.refs||[])].slice(0,10)):node.type==='drug'?(node.data.med?.refs||[]):node.type==='condition'?(node.data.condition?.refs||[]):uniq((node.data.links||[]).flatMap(x=>x.refs||[])).slice(0,10),shared=node.data.sharedness??1,importance=node.data.importance??node.data.pathway?.importance,maxBenefit=node.data.maxBenefit;
 let extra='';if(node.type==='drug')extra=`<p class="node-summary"><b>Primary target:</b> ${esc(node.data.med.primary)}<br><b>Direct action:</b> ${esc(node.data.med.direct)}<br><b>Secondary signaling:</b> ${esc(node.data.med.secondary)}</p>`;if(node.type==='pathway'&&node.data.aggregate){const names=[...node.data.aggregate.conditions].map(id=>COND[id]?.abbr).filter(Boolean);extra=`<p class="node-summary"><b>Condition coverage:</b> ${esc(names.join(', ')||'Pharmacologic target hub only')}<br><b>Maximum embedded importance:</b> ${node.data.importance||'—'}/5${node.data.synthetic?'<br><b>Note:</b> no standalone disease-pathway row; placement is target-ontology based.':''}</p>`}
 $('#nodeInfo').innerHTML=`<h4>${esc(node.label)}</h4><span class="network-badge" style="border-color:${node.color};color:${node.color}">${esc(typeLabel)}</span><p class="node-summary">${esc(node.detail)}</p>${extra}<div class="network-mini-grid"><div><small>Evidence</small><b>${gradeBadge(node.grade)}</b></div><div><small>Visible degree</small><b>${visibleRelationsForNode(node.id).filter(e=>e.visible).length}/${node.degree}</b></div><div><small>${networkMode==='unified'?'Condition sharedness':'Importance / benefit'}</small><b>${networkMode==='unified'?shared:(importance??maxBenefit??'—')}${networkMode==='unified'?' conditions':'/5'}</b></div><div><small>Placement logic</small><b>${esc(nodePositionText(node))}</b></div></div>${refs.length?`<div class="network-ref-list"><small>Sources</small>${refChips(refs)}</div>`:''}`;
 const rels=visibleRelationsForNode(node.id).slice(0,24);$('#networkRelations').innerHTML=rels.map(e=>{const other=networkNodes.find(n=>n.id===(e.source===node.id?e.target:e.source)),col=EDGE_STYLE[e.type]?.color||'#94a3b8';return `<button class="network-relation ${e.visible?'':'hidden-relation'}" style="--edge-color:${col}" data-edge="${e.id}" data-node="${other?.id||''}"><b>${esc(other?.label||'')}</b><small>${esc(EDGE_STYLE[e.type]?.label||e.type)} · ${e.strength}/5 · grade ${e.grade}${e.visible?'':' · hidden by current filter'}</small></button>`}).join('')||'<span class="muted">No relationships in the embedded graph.</span>';
 $$('.network-relation').forEach(b=>b.onclick=()=>{const n=networkNodes.find(x=>x.id===b.dataset.node);if(n){networkSelected=n;applyNetworkFilters();renderNetworkInspector(n);updateNetworkStats();draw3D()}})
}
function renderNetworkLegend(){$('#networkLegend').innerHTML=`<div class="legend-group"><b>Node geometry</b><div class="legend-row" style="color:#94a3b8"><i class="shape-demo hex"></i><span>Condition / disease context</span></div><div class="legend-row" style="color:#22d3ee"><i class="shape-demo circle"></i><span>Immune pathway or cytokine program</span></div><div class="legend-row" style="color:#34d399"><i class="shape-demo square"></i><span>Medication / intervention</span></div><div class="legend-row" style="color:#f59e0b"><i class="shape-demo diamond"></i><span>Clinical manifestation or organ domain</span></div></div><div class="legend-group"><b>Directed relationship semantics</b>${Object.entries(EDGE_STYLE).map(([k,v])=>`<div class="legend-row" style="color:${v.color}"><i class="edge-demo ${v.dash.length?'dashed ':''}${v.end==='bar'?'inhibit':'arrow'}"></i><span>${esc(v.label)}</span></div>`).join('')}</div><div class="legend-group"><b>Magnitude and confidence</b><div>Node size = pathway importance, treatment benefit, or cross-condition sharedness.</div><div>Node border/fill and edge opacity = evidence grade. Edge width = relationship strength.</div><div>A second flat outline marks entities shared by at least four conditions. Selection uses a heavier white outline.</div></div><div class="legend-group"><b>Coordinate system</b><div>X = causal stage; Y = immune family or organ domain; Z = intervention below, mechanism center, phenotype above.</div><div>Bundled cubic routes preserve source/target lanes; they do not imply unmeasured molecular intermediates.</div></div>`}
function updateNetworkStats(){const vn=networkNodes.filter(n=>n.visible).length,ve=networkEdges.filter(e=>e.visible).length,shared=networkMode==='unified'?` · shared ≥${$('#networkSharedMin').value}`:'';$('#networkStats').innerHTML=`<strong>${vn} nodes · ${ve} edges</strong><br>${networkMode==='condition'?'condition cascade':'unified atlas'}${shared} · ${$('#networkDensity').value}${networkIsolate?' · isolated':''}`}
function nearestNetworkHit(clientX,clientY){const r=nCanvas.getBoundingClientRect(),x=clientX-r.left,y=clientY-r.top,ns=networkNodes.filter(n=>n.visible).map(transformed).map(n=>({type:'node',obj:n,d:Math.hypot(n.sx-x,n.sy-y)-Math.max(4,n.size*n.scale)})).sort((a,b)=>a.d-b.d);if(ns[0]&&ns[0].d<10)return ns[0];const nodeMap=Object.fromEntries(networkNodes.map(transformed).map(n=>[n.id,n]));let best=null;networkEdges.filter(e=>edgeShouldDraw(e,nodeMap)).forEach(e=>{const A=nodeMap[e.source],B=nodeMap[e.target],[c1,c2]=edgeControls3D(e,A,B).map(projectPoint);let d=Infinity;for(let i=0;i<=24;i++){const p=cubicPoint(A,c1,c2,B,i/24);d=Math.min(d,Math.hypot(p.x-x,p.y-y))}if(d<7&&(!best||d<best.d))best={type:'edge',obj:e,d}});return best}
function focusNodeByLabel(value){const q=norm(value).trim();if(!q)return;const n=networkNodes.find(x=>norm(x.label)===q)||networkNodes.find(x=>norm(x.label).includes(q));if(n){networkSelected=n;applyNetworkFilters();renderNetworkInspector(n);updateNetworkStats();panX=0;panY=0;draw3D()}}
function setViewPreset(p){if(p==='iso'){rotX=.34;rotY=-.50;rotZ=0;zoom=networkMode==='unified'?.56:.73}else if(p==='front'){rotX=0;rotY=0;rotZ=0;zoom=networkMode==='unified'?.56:.67}else if(p==='therapy'){rotX=1.02;rotY=-.23;rotZ=0;zoom=networkMode==='unified'?.52:.64}else{rotX=.15;rotY=-1.28;rotZ=0;zoom=networkMode==='unified'?.58:.76}panX=0;panY=0;draw3D()}
function startNetworkTour(){if(networkTourTimer){clearInterval(networkTourTimer);networkTourTimer=null;$('#networkTour').textContent='Trace supported chain';return}let seq;if(networkMode==='condition'){const cid=$('#networkCondition').value,condition=networkNodes.find(n=>n.id===`c:${cid}`),paths=networkNodes.filter(n=>n.type==='pathway').sort((a,b)=>(a.data.stage||0)-(b.data.stage||0)||(b.data.importance||0)-(a.data.importance||0)).slice(0,5),manifest=networkNodes.filter(n=>n.type==='manifestation').sort((a,b)=>b.degree-a.degree)[0],drug=networkNodes.filter(n=>n.type==='drug').sort((a,b)=>(b.data.maxBenefit||0)-(a.data.maxBenefit||0))[0];seq=[condition,...paths,manifest,drug].filter(Boolean)}else{seq=[networkNodes.filter(n=>n.type==='condition').sort((a,b)=>b.degree-a.degree)[0],...networkNodes.filter(n=>n.type==='pathway').sort((a,b)=>(b.data.sharedness||0)-(a.data.sharedness||0)).slice(0,5),networkNodes.filter(n=>n.type==='manifestation').sort((a,b)=>(b.data.sharedness||0)-(a.data.sharedness||0))[0],networkNodes.filter(n=>n.type==='drug').sort((a,b)=>(b.data.sharedness||0)-(a.data.sharedness||0))[0]].filter(Boolean)}if(!seq.length){$('#networkTour').textContent='No supported chain';return}let i=0;const step=()=>{networkSelected=seq[i%seq.length];applyNetworkFilters();renderNetworkInspector(networkSelected);updateNetworkStats();draw3D();i++};step();$('#networkTour').textContent='Stop trace';networkTourTimer=setInterval(step,1900)}
nCanvas.addEventListener('pointerdown',e=>{networkDrag=true;networkPanMode=e.shiftKey;networkLast={x:e.clientX,y:e.clientY};nCanvas.setPointerCapture(e.pointerId)});
nCanvas.addEventListener('pointermove',e=>{if(networkDrag){const dx=e.clientX-networkLast.x,dy=e.clientY-networkLast.y;if(networkPanMode){panX+=dx;panY+=dy}else{rotY+=dx*.0065;rotX+=dy*.0065;rotX=Math.max(-1.45,Math.min(1.45,rotX))}networkLast={x:e.clientX,y:e.clientY};draw3D();return}const hit=nearestNetworkHit(e.clientX,e.clientY);networkHovered=hit?.type==='node'?hit.obj:null;networkHoveredEdge=hit?.type==='edge'?hit.obj:null;if(networkHovered)tip(`<b>${esc(networkHovered.label)}</b><br>${esc(networkHovered.type)} · ${networkHovered.degree} links · grade ${networkHovered.grade}`,e.clientX,e.clientY);else if(networkHoveredEdge)tip(`<b>${esc(networkHoveredEdge.label)}</b><br>${esc(EDGE_STYLE[networkHoveredEdge.type]?.label||networkHoveredEdge.type)} · ${networkHoveredEdge.strength}/5 · grade ${networkHoveredEdge.grade}`,e.clientX,e.clientY);else hideTip();draw3D()});
nCanvas.addEventListener('pointerup',e=>{networkDrag=false;nCanvas.releasePointerCapture(e.pointerId)});nCanvas.addEventListener('pointerleave',()=>{networkHovered=null;networkHoveredEdge=null;hideTip();draw3D()});nCanvas.addEventListener('wheel',e=>{e.preventDefault();zoom*=e.deltaY>0?.91:1.10;zoom=Math.max(.22,Math.min(2.2,zoom));draw3D()},{passive:false});
nCanvas.addEventListener('click',e=>{const hit=nearestNetworkHit(e.clientX,e.clientY);if(hit?.type==='node'){networkSelected=networkSelected?.id===hit.obj.id?null:networkNodes.find(n=>n.id===hit.obj.id);applyNetworkFilters();renderNetworkInspector(networkSelected);updateNetworkStats();draw3D()}else if(hit?.type==='edge'){networkSelected=null;applyNetworkFilters();renderNetworkInspector(null,hit.obj);updateNetworkStats();draw3D()}else{networkSelected=null;applyNetworkFilters();renderNetworkInspector();updateNetworkStats();draw3D()}});
nCanvas.addEventListener('dblclick',()=>{panX=0;panY=0;zoom=networkMode==='unified'?.56:.73;draw3D()});
